#@title 2. 実験用の文字列を用意する
source_mode = "デモ：数字4桁" #@param ["デモ：数字4桁", "デモ：単語＋数字", "自動生成", "自分で入力"]
password_length = 4 #@param {type:"integer"}
use_digits = True #@param {type:"boolean"}
use_lower = True #@param {type:"boolean"}
use_upper = True #@param {type:"boolean"}
use_symbols = False #@param {type:"boolean"}

experiment = None
storage_comparison = None
password = None
generation_alphabet = None
if source_mode == "デモ：数字4桁":
    password = "4729"
elif source_mode == "デモ：単語＋数字":
    password = "sakura2026"
elif source_mode == "自動生成":
    generation_alphabet = alphabet_for(use_digits, use_lower, use_upper, use_symbols)
    password = generate_password(password_length, generation_alphabet)
else:
    from getpass import getpass
    password = getpass("実験用の文字列：")
validate_password(password)
if source_mode != "自分で入力":
    print("今回の実験用文字列：", password)
print("文字列を用意できました。セル3で、探す側の手がかりを選びましょう。")

#@title 3. 探す側の手がかりを選び、実際に試す
attack_knowledge = "手がかりなし" #@param ["手がかりなし", "文字の種類・文字数を指定", "文字の並び・一部を指定"]
#@markdown 「手がかりなし」は最大文字数だけを使います。
search_max_length = 6 #@param {type:"integer"}
#@markdown 「文字の種類・文字数を指定」で使う条件
attack_digits = True #@param {type:"boolean"}
attack_lower = False #@param {type:"boolean"}
attack_upper = False #@param {type:"boolean"}
attack_symbols = False #@param {type:"boolean"}
length_known = True #@param {type:"boolean"}
search_length = 4 #@param {type:"integer"}
#@markdown 「文字の並び・一部を指定」で使う条件。例：先頭 sakura ＋ 数字4文字
fixed_prefix = "" #@param {type:"string"}
character_group_1 = "数字" #@param ["数字", "小文字", "大文字", "英字", "英数字", "記号", "すべて", "なし"]
group_1_count = 4 #@param {type:"integer"}
character_group_2 = "なし" #@param ["数字", "小文字", "大文字", "英字", "英数字", "記号", "すべて", "なし"]
group_2_count = 0 #@param {type:"integer"}
fixed_suffix = "" #@param {type:"string"}
seconds_per_method = 2 #@param {type:"slider", min:1, max:10, step:1}
candidate_limit = 100000 #@param {type:"integer"}

experiment = None
storage_comparison = None
attack = make_attack(attack_knowledge,
    digits=attack_digits, lower=attack_lower, upper=attack_upper, symbols=attack_symbols,
    length_known=length_known, search_length=search_length, search_max_length=search_max_length,
    prefix=fixed_prefix, suffix=fixed_suffix,
    group1=character_group_1, group1_count=group_1_count,
    group2=character_group_2, group2_count=group_2_count)
print("今回の探す範囲：", attack["preview"])
print(f"候補の組み合わせ：{attack['candidates']:,}通り")
experiment = run_experiment(password, attack,
    seconds=float(seconds_per_method), limit=int(candidate_limit), include_gpu=gpu_enabled)

show_table(experiment["trials"], [
    ("method", "探し方"), ("state", "結果"), ("tested", "調べた件数"),
    ("seconds", "時間（秒）"), ("rate", "件／秒"), ("engine", "実行方式"),
])
found_rows = [r for r in experiment["trials"] if r["state"] == "発見"]
if found_rows:
    quickest = min(found_rows, key=lambda row: row["seconds"])
    print(f"今回は「{quickest['method']}」で最も短時間に見つかりました。")
    if any(r["method"] in ("辞書", "単語の変形") for r in found_rows):
        print("単語やよくある規則で予想できる文字列でした。長さだけでは強さを判断できない例です。")
else:
    print("この実験では未発見でした。探す条件が合っていない場合もあり、安全とは判断できません。")

print("\n同じ候補を調べる速さ（同じ件数を3回測定した中央値）")
show_table(experiment["benchmarks"], [
    ("engine", "実行方式"), ("state", "状態"), ("count", "候補数"),
    ("seconds", "時間（秒）"), ("rate", "件／秒"),
    ("prepare_seconds", "初回準備（秒）"), ("reason", "利用できない理由"),
])
print("使った方式：", experiment["fastest_engine"])
if attack["mode"] == "structure":
    print("並び指定では位置ごとに使える文字が異なるため、Python hashlibで別に測定します。")
else:
    print("攻撃側の最大文字数で代表速度を測り、総当たりには最も速い方式を使います。")
    print("GPUを使う場合はセル1のgpu_enabledを有効にし、GPUランタイムで上から実行してください。")
